def add_todo(todos, item, path=None):
    if not item:
        raise ValueError("item cannot be empty")
    todos.append({"item": item, "done": False})
    if path is not None:
        save_todos(todos, path)
    return todos


def complete_todo(todos, item, path=None):
    for todo in todos:
        if todo["item"] == item:
            todo["done"] = True
